SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷260", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。疑似转录讹字保留并单独注明。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/tongjian/260.txt", "note": "卷260乾宁二年条；书、卷、年、段落及行号见批次账本。", "id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"title": "吴越备史·卷1·董昌称帝及谏者", "source_type": "primary", "author": "范坰、林禹", "edition": "Kanripo四部丛刊本电子转录；保留异体字与版页标记，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/originals/kanripo/KR2i0019/KR2i0019_001.txt", "note": "乾宁二年称帝段及乾宁三年平董昌段内追述；逐条注明追叙位置。", "id": "524231bf-baaf-5e7c-b3dc-e9296273d53a"}]'::jsonb)
