INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "董昌议称帝，召将佐商议", "start_year": 895, "end_year": 895, "time_original": "895年二月即帝以前；确日未载", "dynasty": "唐", "description": "董昌准备称帝，召集将佐商议。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "8d31ffce-eafe-5c58-b0f4-025d61809687"}, {"title": "黄碣以受唐恩与灭族之危谏董昌", "start_year": 895, "end_year": 895, "time_original": "895年二月即帝以前；确日未载", "dynasty": "唐", "description": "节度副使黄碣劝董昌继续奉唐，指出其受朝廷厚恩、位至将相，并表示宁死为忠臣。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "8338e960-a16a-5371-8418-bf92b011c6eb"}, {"title": "董昌杀黄碣及其家八十口", "start_year": 895, "end_year": 895, "time_original": "895年称帝议论期间；确日未载", "dynasty": "唐", "description": "董昌怒斥黄碣惑众，斩黄碣，将首级投厕；又杀其家八十口，同坑埋葬。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "1961a872-554e-5ed8-ba70-76fa482b85c1"}, {"title": "会稽令吴镣谏称帝，遭董昌族诛", "start_year": 895, "end_year": 895, "time_original": "895年称帝以前；确日未载", "dynasty": "唐", "description": "董昌询问会稽令吴镣，吴镣劝其保诸侯之位以传子孙，反对称帝；董昌族诛吴镣。", "phases": [], "location_name": "会稽", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "62284c76-a6c3-5851-8ef4-6bb421ad7005"}, {"title": "张逊拒称帝之议，遭董昌杀害", "start_year": 895, "end_year": 895, "time_original": "895年称帝以前；确日未载", "dynasty": "唐", "description": "董昌许诺称帝后让山阴令张逊知御史台。张逊以浙东六州未必服从、李锜刘辟前例等劝谏，董昌杀之。", "phases": [], "location_name": "山阴、浙东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d671adb7-8da4-50c5-91e9-d9edc244d860"}, {"title": "董昌登子城门楼称帝，陈瑞物示众", "start_year": 895, "end_year": 895, "time_original": "895年二月辛卯", "dynasty": "唐", "description": "董昌着礼服登子城门楼即皇帝位，将瑞物陈列于庭示众。", "phases": [], "location_name": "子城门楼、庭", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cecd3312-81eb-5c8e-8690-6b0e5f0f630b"}, {"title": "吴越民间流传罗平天册鸟讹言", "start_year": null, "end_year": null, "time_original": "咸通末；段内追叙，确年未载", "dynasty": "唐", "description": "《通鉴》追述咸通末吴越间流传山中四目三足鸟的讹言，民间绘像祭祀。", "phases": [], "location_name": "吴、越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1a4fbdc7-a180-588d-93a0-b32095a9abfb"}, {"title": "董昌定大越罗平国号与顺天年号", "start_year": 895, "end_year": 895, "time_original": "895年二月称帝后；确日未另载", "dynasty": "唐", "description": "董昌自称大越罗平国，改元顺天，将城楼题为天册之楼，令群下称其圣人。", "phases": [], "location_name": "天册之楼", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e03d429d-5916-5a1f-a8fc-3f7ec79c129a"}, {"title": "董昌任李邈等四人为相", "start_year": 895, "end_year": 895, "time_original": "895年称帝后；确日未另载", "dynasty": "唐", "description": "董昌以前杭州刺史李邈、前婺州刺史蒋瑰、两浙盐铁副使杜郢、前屯田郎中李瑜为相。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "0e6a0ccd-fa4b-57fc-af39-784c45697afb"}, {"title": "董昌以吴瑶等为翰林，李畅之等为大将军", "start_year": 895, "end_year": 895, "time_original": "895年称帝后；确日未另载", "dynasty": "唐", "description": "董昌以吴瑶等为翰林学士，李畅之等为大将军。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f0b41fac-4529-53ec-9eb0-54faba83881a"}, {"title": "董昌告钱镠即国位，称授都指挥使", "start_year": 895, "end_year": 895, "time_original": "895年称帝后；确日未另载", "dynasty": "唐", "description": "董昌移书钱镠，称权即罗平国位，并以钱镠为两浙都指挥使。", "phases": [], "location_name": "两浙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c20531a1-0c98-5a51-a0ae-fc558bf3108a"}, {"title": "钱镠书劝董昌悔改，董昌不听", "start_year": 895, "end_year": 895, "time_original": "895年董昌称帝后；确日未另载", "dynasty": "唐", "description": "钱镠致书劝董昌放弃称帝，保节度使之位并及时悔改；董昌不听。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "79ce53b7-3923-5308-a545-8c67739ffe34"}, {"title": "钱镠将兵三万至越州迎恩门再谏", "start_year": 895, "end_year": 895, "time_original": "895年书劝不听后；确日未另载", "dynasty": "唐", "description": "钱镠将兵三万到越州城下，于迎恩门见董昌，再拜劝其改过，警告朝廷出师将累及乡里士民。", "phases": [], "location_name": "越州城下、迎恩门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7b3994a0-61c8-539a-b04f-858abc88836e"}, {"title": "董昌犒军，送吴瑶及巫觋请待罪", "start_year": 895, "end_year": 895, "time_original": "895年钱镠城下劝谏后；确日未另载", "dynasty": "唐", "description": "董昌惧，送犒军钱二百万，将首谋者吴瑶与巫觋数人交给钱镠，并请求待罪于天子。", "phases": [], "location_name": "越州城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "10504481-a938-5ee2-9344-89b6cd8b82ec"}, {"title": "钱镠引兵还，将董昌事上报", "start_year": 895, "end_year": 895, "time_original": "895年董昌送犒请待罪后；确日未另载", "dynasty": "唐", "description": "钱镠撤回军队，将董昌之事上报朝廷。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "6995f9e2-08bf-535e-8398-b135c5ca6c0e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

