INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "董昌准备称帝，召集将佐商议。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：董昌将称帝，集将佐议之。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "a6b759ab-6bf3-5267-ae32-bef67ec66a86", "subject_id": "8d31ffce-eafe-5c58-b0f4-025d61809687", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "895年二月即帝以前；确日未载", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：董昌将称帝，集将佐议之。；核对说明：干支日未换算公历日。", "status": "draft", "id": "f2c65f04-cc40-5f86-a244-3062b596b40f", "subject_id": "8d31ffce-eafe-5c58-b0f4-025d61809687", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记董昌：准备称帝召议者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：董昌将称帝，集将佐议之。节度副使黄碣曰：“今唐室虽微，天人未厌。齐桓、晋文皆翼戴周室以成霸业。大王兴于畎亩，受朝廷厚恩，位至将相，富贵极矣，奈何一旦忽为族灭之计乎！碣宁死为忠臣，不生为叛逆！”昌怒，以为惑众，斩之，投其首于厕中，骂之曰：“奴贼负我！好圣明时三公不能待，而先求死也！”并杀其家八十口，同坎瘗之。又问会稽令吴镣，对曰：“大王不为真诸侯以传子孙，乃欲假天子以取灭亡邪！”昌亦族诛之。又谓山阴令张逊曰：“汝有能政，吾深知之，俟吾为帝，命汝知御史台。”逊曰：“大王起石镜镇，建节浙东，荣贵近二十年，何苦效李锜、刘辟之所为乎！浙东僻处海隅，巡属虽有六州，大王若称帝，彼必不从，徒守孤城，为天下笑耳！”昌又杀之，谓人曰：“无此三人者，则人莫我违矣！”二月，辛卯，昌被兗冕登子城门楼，即皇帝位。悉陈瑞物于庭以示众。先是，咸通末，吴、越间讹言山中有大鸟，四目三足，声云“罗平天册”，见者有殃，民间多画像以祀之。及昌僭号，曰：“此吾鸑鷟也。”乃自称大越罗平国，改元顺天，署城楼曰天册之楼，令群下谓己曰：“圣人”。以前杭州刺史李邈、前婺州刺史蒋瑰、两浙盐铁副使杜郢、前屯田郎中李瑜为相。又以吴瑶等皆为翰林学士、李畅之等皆为大将军。昌移书钱镠，告以权即罗平国位，以镠为两浙都指挥使。镠遗昌书曰：“与其闭门作天子，与九族、百姓俱陷涂炭，岂若开门作节度使，终身富贵邪！及今悛悔，尚可及也！”昌不听，镠乃将兵三万诣越州城下，至迎恩门见昌，再拜言曰：“大王位兼将相，奈何舍安就危！镠将兵此来，以俟大王改过耳。若天子命将出师，纵大王不自惜，乡里士民何罪，随大王族灭乎！”昌惧，致犒军钱二百万，执首谋者吴瑶及巫觋数人送于镠，且请待罪天子。镠引兵还，以状闻。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "460528fe-d46c-5124-8d9b-ffd0e03d47fe", "subject_id": "873d5b10-b461-5308-baa9-da26022436b4", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "董昌：准备称帝召议者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：董昌将称帝，集将佐议之。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "cac6b15f-8432-5e33-9432-aea5b01b5754", "subject_id": "0e6ba171-fa47-5a81-be34-2a303fb37e43", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "description", "claim_text": "节度副使黄碣劝董昌继续奉唐，指出其受朝廷厚恩、位至将相，并表示宁死为忠臣。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：节度副使黄碣曰：“今唐室虽微，天人未厌。齐桓、晋文皆翼戴周室以成霸业。大王兴于畎亩，受朝廷厚恩，位至将相，富贵极矣，奈何一旦忽为族灭之计乎！碣宁死为忠臣，不生为叛逆！”；核对说明：黄碣复用884年婺州刺史人物；本段任副使。齐桓晋文为引述典故，不列本年在场人物；族灭之计为劝谏风险。", "status": "draft", "id": "b20828d8-f28a-5ab1-97b2-e6a62b4c41c6", "subject_id": "8338e960-a16a-5371-8418-bf92b011c6eb", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "895年二月即帝以前；确日未载", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：节度副使黄碣曰：“今唐室虽微，天人未厌。齐桓、晋文皆翼戴周室以成霸业。大王兴于畎亩，受朝廷厚恩，位至将相，富贵极矣，奈何一旦忽为族灭之计乎！碣宁死为忠臣，不生为叛逆！”；核对说明：黄碣复用884年婺州刺史人物；本段任副使。齐桓晋文为引述典故，不列本年在场人物；族灭之计为劝谏风险。", "status": "draft", "id": "bed50917-c22c-5e69-8e3a-599baa598e29", "subject_id": "8338e960-a16a-5371-8418-bf92b011c6eb", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记黄碣：反对称帝谏者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：董昌将称帝，集将佐议之。节度副使黄碣曰：“今唐室虽微，天人未厌。齐桓、晋文皆翼戴周室以成霸业。大王兴于畎亩，受朝廷厚恩，位至将相，富贵极矣，奈何一旦忽为族灭之计乎！碣宁死为忠臣，不生为叛逆！”昌怒，以为惑众，斩之，投其首于厕中，骂之曰：“奴贼负我！好圣明时三公不能待，而先求死也！”并杀其家八十口，同坎瘗之。又问会稽令吴镣，对曰：“大王不为真诸侯以传子孙，乃欲假天子以取灭亡邪！”昌亦族诛之。又谓山阴令张逊曰：“汝有能政，吾深知之，俟吾为帝，命汝知御史台。”逊曰：“大王起石镜镇，建节浙东，荣贵近二十年，何苦效李锜、刘辟之所为乎！浙东僻处海隅，巡属虽有六州，大王若称帝，彼必不从，徒守孤城，为天下笑耳！”昌又杀之，谓人曰：“无此三人者，则人莫我违矣！”二月，辛卯，昌被兗冕登子城门楼，即皇帝位。悉陈瑞物于庭以示众。先是，咸通末，吴、越间讹言山中有大鸟，四目三足，声云“罗平天册”，见者有殃，民间多画像以祀之。及昌僭号，曰：“此吾鸑鷟也。”乃自称大越罗平国，改元顺天，署城楼曰天册之楼，令群下谓己曰：“圣人”。以前杭州刺史李邈、前婺州刺史蒋瑰、两浙盐铁副使杜郢、前屯田郎中李瑜为相。又以吴瑶等皆为翰林学士、李畅之等皆为大将军。昌移书钱镠，告以权即罗平国位，以镠为两浙都指挥使。镠遗昌书曰：“与其闭门作天子，与九族、百姓俱陷涂炭，岂若开门作节度使，终身富贵邪！及今悛悔，尚可及也！”昌不听，镠乃将兵三万诣越州城下，至迎恩门见昌，再拜言曰：“大王位兼将相，奈何舍安就危！镠将兵此来，以俟大王改过耳。若天子命将出师，纵大王不自惜，乡里士民何罪，随大王族灭乎！”昌惧，致犒军钱二百万，执首谋者吴瑶及巫觋数人送于镠，且请待罪天子。镠引兵还，以状闻。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "cb005c7e-f033-5cf0-8f24-902e42ad4132", "subject_id": "ef6a7e30-fbb2-51eb-8fbc-1ad1ccc58632", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "黄碣：反对称帝谏者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：节度副使黄碣曰：“今唐室虽微，天人未厌。齐桓、晋文皆翼戴周室以成霸业。大王兴于畎亩，受朝廷厚恩，位至将相，富贵极矣，奈何一旦忽为族灭之计乎！碣宁死为忠臣，不生为叛逆！”；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "2b0df728-6d51-58c5-9a90-d61bfe105222", "subject_id": "a5e3b011-f975-52d8-bd85-5d047c13edec", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "董昌：受谏者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：节度副使黄碣曰：“今唐室虽微，天人未厌。齐桓、晋文皆翼戴周室以成霸业。大王兴于畎亩，受朝廷厚恩，位至将相，富贵极矣，奈何一旦忽为族灭之计乎！碣宁死为忠臣，不生为叛逆！”；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "85990ca9-a676-544b-848f-6e790059b54d", "subject_id": "ba25dd22-70dd-566c-9797-ff9a5f38c92d", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "description", "claim_text": "董昌怒斥黄碣惑众，斩黄碣，将首级投厕；又杀其家八十口，同坑埋葬。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：昌怒，以为惑众，斩之，投其首于厕中，骂之曰：“奴贼负我！好圣明时三公不能待，而先求死也！”并杀其家八十口，同坎瘗之。；核对说明：八十口仅黄家；三公为董昌怒语，不当黄碣已有三公官职。", "status": "draft", "id": "ce8f08fd-d704-5586-b8b3-a648c330cf68", "subject_id": "1961a872-554e-5ed8-ba70-76fa482b85c1", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "895年称帝议论期间；确日未载", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p006·原文件第11行", "note": "原文：昌怒，以为惑众，斩之，投其首于厕中，骂之曰：“奴贼负我！好圣明时三公不能待，而先求死也！”并杀其家八十口，同坎瘗之。；核对说明：八十口仅黄家；三公为董昌怒